function dateAt(offset){let d=new Date(BASE+'T12:00:00Z');d.setUTCDate(d.getUTCDate()+offset);return d.toISOString().slice(0,10);}
function daysUntil(date,offset=0){if(!date)return null;return Math.round((new Date(date+'T12:00:00Z')-new Date(dateAt(offset)+'T12:00:00Z'))/86400000);}
function fresh(){return {version:1,setup:false,buddy:'Rami',name:'Omar',style:'Warm',color:'teal',intent:'A new chapter',arrival:'2026-09-21',salaryDate:'2026-10-01',homeEnd:'2026-10-08',visaExpiry:'2026-11-20',workplace:'Al Maryah Island',hours:'09:00–18:00',budget:6500,salary:14000,available:4200,essential:2800,wellbeingBudget:300,interests:['Outdoors','Music'],feeling:'Steady',pace:'Balanced',quietStart:'22:00',quietEnd:'08:00',memory:true,reminders:true,paused:false,day:0,income:'unknown',medical:'unconfirmed',home:'temporary',wellbeing:false,complete:['arrival','work'],snoozed:{},saved:[],messages:[],revisions:[],receipts:[],connections:{appointment:false},events:[],demoStep:0,lastPromptDay:null};}
